solution:
import { useState } from 'react';

export function useMapState(initial = {}) {
  const [map, setMap] = useState(initial);
  return {
    map,
    set: (key, value) => setMap(m => ({ ...m, [key]: value })),
    get: (key) => map[key],
    remove: (key) => setMap(m => { const n = { ...m }; delete n[key]; return n; }),
    has: (key) => Object.prototype.hasOwnProperty.call(map, key),
    clear: () => setMap({}),
  };
}
